export const lessons = [
  { id: 1, track: 'foundations', title: 'How a model learns', description: 'Data, parameters, losses, and the difference between training and inference.', concept: 'A model learns by updating parameters to reduce a loss on training examples. Evaluate the result on separate data.', objectives: ['Identify inputs, targets, and trainable parameters.', 'Explain one gradient update and why held-out data matters.'], practice: 'Run a supplied training loop. Change the learning rate and compare training and validation curves.', evidence: 'An annotated learning curve and an explanation of one failed training run.', lab: 'A · Representations & attention', reads: ['pytorch'] },
  { id: 2, track: 'foundations', title: 'Text and images become vectors', description: 'Text tokens, image patches, embeddings, and sequence length.', concept: 'A text token and an image patch have different meanings, but both can be represented as a vector in a sequence.', objectives: ['Trace text through tokenization and embedding.', 'Split an image into patches and calculate the resulting sequence length.'], practice: 'Inspect tokens for Chinese, English, and code. Patchify a small image and compare two patch sizes.', evidence: 'A diagram with tensor dimensions and a comparison of sequence lengths.', lab: 'A · Representations & attention', reads: ['hf-llm', 'vit'] },
  { id: 3, track: 'transformer', title: 'Attention, one operation at a time', description: 'Queries, keys, values, similarity scores, and softmax.', concept: 'Attention computes a weighted combination of value vectors. The weights depend on comparisons between a query and the keys.', objectives: ['Calculate attention on a small numerical example.', 'Track the dimensions of Q, K, V, and the attention matrix.'], practice: 'Implement scaled dot-product attention and compare your output with a supplied reference.', evidence: 'A correct numerical example and a working attention function.', lab: 'A · Representations & attention', reads: ['attention'] },
  { id: 4, track: 'transformer', title: 'Masks and multiple heads', description: 'Causal visibility, parallel attention heads, and cross-attention.', concept: 'A mask controls which positions can contribute. Multiple heads apply different learned projections before their outputs are combined.', objectives: ['Explain causal versus bidirectional attention.', 'Distinguish self-attention from cross-attention.'], practice: 'Change future tokens and verify that earlier causal outputs stay unchanged. Inspect two attention heads.', evidence: 'A masking check and a diagram of multi-head attention dimensions.', lab: 'A · Representations & attention', reads: ['attention'] },
  { id: 5, track: 'transformer', title: 'Build a Transformer block', description: 'Attention, feed-forward layers, residual paths, and normalization.', concept: 'A Transformer block combines communication between positions with transformations applied to each position.', objectives: ['Assemble a block from attention and feed-forward components.', 'Explain the purpose of residual paths and normalization.'], practice: 'Complete a small block in a supplied framework and inspect its intermediate tensors.', evidence: 'A runnable block and an annotated forward-pass diagram.', lab: 'B · One block, two applications', reads: ['attention', 'pytorch'] },
  { id: 6, track: 'transformer', title: 'Positions, depth, and computation', description: 'Positional information, stacked blocks, and attention cost.', concept: 'Models need a way to represent position. Increasing sequence length also increases the size of a full attention matrix.', objectives: ['Explain why positional information is needed.', 'Compare attention-matrix sizes for different sequence lengths.'], practice: 'Inspect a supplied positional encoding and measure attention-matrix size as token count changes.', evidence: 'A position experiment and a small cost table with explicit assumptions.', lab: 'B · One block, two applications', reads: ['attention', 'vit'] },
  { id: 7, track: 'transformer', title: 'A Transformer that writes', description: 'Causal language modeling, next-token targets, and sampling.', concept: 'A language model predicts a distribution over the next token. Generation repeatedly feeds the growing sequence back into the model.', objectives: ['Construct correctly shifted next-token targets.', 'Explain how sampling temperature changes a probability distribution.'], practice: 'Use your block in a miniature language model with a supplied training loop. Compare generation settings.', evidence: 'Held-out prediction loss, generation examples, and a clear account of limitations.', lab: 'B · One block, two applications', reads: ['hf-llm', 'attention'] },
  { id: 8, track: 'transformer', title: 'A Transformer that sees', description: 'Vision Transformers, patch embeddings, and visual recognition.', concept: 'A Vision Transformer processes image patches as a sequence. Its output head and learning target determine the task.', objectives: ['Trace a patch sequence through a visual Transformer.', 'Compare image classification with causal text generation.'], practice: 'Adapt the shared block to a small image-classification task using a supplied data and training pipeline.', evidence: 'Held-out accuracy, error examples, and a text-versus-image architecture comparison.', lab: 'B · One block, two applications', reads: ['vit'] },
  { id: 9, track: 'foundations', title: 'Pretrain once, adapt carefully', description: 'Visual self-supervision, frozen features, instruction tuning, and LoRA.', concept: 'Pretraining and downstream adaptation solve different problems. A useful comparison keeps data and evaluation conditions explicit.', objectives: ['Compare frozen-feature transfer with parameter updates.', 'Distinguish prompting, instruction tuning, and efficient adaptation.'], practice: 'Fit the same linear classifier to random and pretrained visual features. Analyze supplied instruction-tuning results.', evidence: 'A matched transfer comparison and a concise adaptation decision.', lab: 'B · One block, two applications', reads: ['dino', 'hf-llm'] },
  { id: 10, track: 'vision', title: 'From noise to an image', description: 'Diffusion, conditional generation, latent patches, and DiT.', concept: 'A diffusion model learns a denoising-related prediction and uses repeated sampling steps to generate an image. A Transformer can serve as its backbone.', objectives: ['Identify the training target and sampling process.', 'Explain how timestep and task conditioning enter a visual generator.'], practice: 'Complete a toy denoising exercise. Compare sampling steps on a supplied image-generation service.', evidence: 'A denoising visualization and a controlled quality–cost comparison.', lab: 'C · Generation & multimodal alignment', reads: ['diffusion', 'dit'] },
  { id: 11, track: 'vision', title: 'Connect vision and language', description: 'Image–text alignment, retrieval, visual instruction following, and grounding.', concept: 'Matching an image with text and generating an answer about an image are different tasks, with different objectives and failure modes.', objectives: ['Explain image–text similarity and cross-modal retrieval.', 'Identify statements that are unsupported by visual evidence.'], practice: 'Build a small image–text retrieval demo and evaluate a supplied vision–language model on image questions.', evidence: 'Retrieval results and an analysis of grounded and unsupported answers.', lab: 'C · Generation & multimodal alignment', reads: ['clip', 'llava'] },
  { id: 12, track: 'agents', title: 'Give an LLM tools', description: 'Tool schemas, structured arguments, execution, and observations.', concept: 'The model proposes a tool call; application code validates and executes it. The result becomes a new observation for the next decision.', objectives: ['Define a tool with explicit inputs and outputs.', 'Implement a bounded action–observation loop.'], practice: 'Connect an LLM to two simple tools using an explicit Python loop.', evidence: 'Valid tool arguments, correct handling of tool results, and a complete execution trace.', lab: 'D · Build and evaluate an agent', reads: ['react', 'hf-agents'] },
  { id: 13, track: 'agents', title: 'Plan, remember, and stop', description: 'Task decomposition, working state, replanning, and termination.', concept: 'An agent needs a record of what has happened and a concrete way to decide whether to continue or stop.', objectives: ['Compare a fixed workflow with dynamic action selection.', 'Separate working state from retrieved knowledge and persistent memory.'], practice: 'Add task state, a step limit, and recovery from a deliberately failed tool call.', evidence: 'A state-transition diagram and successful termination on normal and failure cases.', lab: 'D · Build and evaluate an agent', reads: ['effective-agents'] },
  { id: 14, track: 'agents', title: 'Ground an agent in text and images', description: 'Document retrieval, visual observations, and evidence-based actions.', concept: 'An agent can combine a language model with visual tools and a knowledge collection. Each observation should inform a subsequent action or conclusion.', objectives: ['Connect retrieval and image inspection to an agent.', 'Trace a recommendation back to evidence from tools.'], practice: 'Investigate a supplied screenshot using project documentation and diagnostic tools.', evidence: 'A task trace linking the screenshot, retrieved sources, actions, and final recommendation.', lab: 'D · Build and evaluate an agent', reads: ['llava', 'effective-agents'] },
  { id: 15, track: 'agents', title: 'Make agents verifiable', description: 'Success criteria, retries, budgets, prompt injection, and failure recovery.', concept: 'A plausible answer does not establish task completion. Check observable outcomes and account for the resources used.', objectives: ['Define an acceptance test for a multi-step task.', 'Diagnose tool-selection, execution, and evidence failures.'], practice: 'Evaluate a direct model response, fixed workflow, and agent on the same task set. Record their information access and budgets.', evidence: 'Task-success results, tool-call counts, and at least three analyzed failure categories.', lab: 'D · Build and evaluate an agent', reads: ['effective-agents', 'react'] },
  { id: 16, track: 'foundations', title: 'Evaluate, explain, and look ahead', description: 'Reproducibility, individual architecture walkthroughs, and emerging applications.', concept: 'A useful result includes the conditions under which it was obtained. Extend a system only after deciding how to measure the proposed benefit.', objectives: ['Explain an architecture and an agent execution trace.', 'Propose a testable extension in video, memory, or embodied interaction.'], practice: 'Reproduce one result and prepare a one-page extension proposal with an evaluation plan.', evidence: 'A reproducible report, an individual code walkthrough, and a bounded extension proposal.', lab: 'Final synthesis', reads: ['dit', 'effective-agents'] },
].map(lesson => ({ ...lesson, hours: 2 }));

